B.alS={[u.c4]:0,[u._]:1,[u.a4]:2,[u.iQ]:3,[u.da]:4,[u.jq]:5,[u.as]:6,[u.G]:7,[u.he]:8,[u.ln]:9,[u.z]:10,"L\u1ef1c 85%, ng\u1eafm th\u1eb3ng tr\u1ecdng t\xe2m bi 1.":11,"L\u1ef1c 78%, tr\xf4 nh\u1eb9 h\u1ed7 tr\u1ee3 n\u1ea3y m\u01b0\u1ee3t m\xe0.":12,[u.k]:13,[u.lt]:14,[u.mx]:15,[u.mA]:16,[u.I]:17,"Ng\u1eafm ch\u1ebb \u0111\xf4i g\xf3c ti\u1ebfp x\xfac, l\u1ef1c 68%.":18,[u.iI]:19,"L\u1ef1c si\xeau \xeam 38%, \u0111\xe1nh ch\xednh t\xe2m bi c\xe1i.":20,[u.af]:21,[u.fo]:22,[u.jF]:23,"L\u1ef1c 78%, mi\u1ebft m\xe9p ngo\xe0i bi 4.":24,"L\u1ef1c m\u1ea1nh 82%, ng\u1eafm n\u1eeda bi 2.":25,"C\u1eaft m\u1ecfng 1/8 bi, l\u1ef1c 62%.":26,[u.f8]:27,"Ng\u1eafm ch\xednh x\xe1c m\xe9p trong, l\u1ef1c 60%.":28,"C\u0103n m\xe1 1/3 bi 4, l\u1ef1c 55%.":29,[u.mE]:30,"L\u1ef1c 68%, ng\u1eafm g\xf3c chu\u1ea9n kh\xf4ng run tay.":31,"L\u1ef1c c\u1ef1c c\u0103ng 85%, gi\u1eef g\u1eady th\u1eadt th\u1eb3ng.":32,"G\xf3c g\u1eady 45 \u0111\u1ed9, l\u1ef1c n\u1ea3y 76%.":33,"Ng\u1eafm ch\xednh x\xe1c ti\u1ebfp tuy\u1ebfn 1/16, l\u1ef1c 64%.":34,[u.jt]:35,"L\u1ef1c \xeam 42%, tr\xf4 nh\u1eb9 ki\u1ec3m so\xe1t.":36,[u.P]:37,"C\u0103n m\xe1 1/2 bi 4, l\u1ef1c 62%.":38,[u.jZ]:39,"G\xf3c c\u01a1 45 \u0111\u1ed9, xo\xe1y dy = 0.50, l\u1ef1c 75%.":40,"L\u1ef1c 72%, \xe1p-ph\xea dx = 0.45.":41,[u.w]:42,"L\u1ef1c 62%, \xe1p-ph\xea nh\u1eb9 dy = 0.20.":43,"L\u1ef1c \xeam \xe1i 40%, kh\xf4ng rung l\u1eafc g\u1eady.":44,"C\u1eaft 1/8 bi, l\u1ef1c 45%.":45,[u.in]:46,"Ng\u1eafm ch\xednh x\xe1c \u0111\u01b0\u1eddng th\u1eb3ng, l\u1ef1c 52%.":47,"G\xf3c c\u01a1 50 \u0111\u1ed9, l\u1ef1c n\u1ea3y 75%.":48,"\u0110\xe1nh th\u1eb3ng t\xe2m bi, l\u1ef1c 48%.":49,"Ng\u1eafm n\u1eeda bi 5, l\u1ef1c 68%.":50,"Mi\u1ebft m\xe9p cao su, l\u1ef1c 55%.":51,"L\u1ef1c 45%, \u0111\xe1nh ch\xednh t\xe2m bi c\xe1i.":52,"G\xf3c g\u1eady 45 \u0111\u1ed9, l\u1ef1c n\u1ea3y 74%.":53,"C\u1eaft m\u1ecfng 1/16, l\u1ef1c 58%.":54,[u.pk]:55}
